#!/usr/bin/env python3
"""Красное у ворот герметичности обязано означать ровно одно.

Ворота отвечают на вопрос «зависит ли набор от домашнего каталога». Строка
«при разном HOME собрано разное: 2435+0 против 2434+1» читается как ответ на
него — и была неправдой. Пока рядом шёл ВТОРОЙ прогон планки по тому же
дереву, один и тот же тест падал у того, кому не достался замок мутаций, и
разница в один тест приезжала в вердикт как зависимость от HOME.

Доказано это не рассуждением. Два прогона `--gate герметичность` по одной
копии дерева, журнал попыток взять замок:

    13:35:27.472 ВЗЯЛ    pid 40415 (ppid 28442) ВоротаБерутКопию
    13:35:29.130 ОТКАЗ   pid 40553 (ppid 28622) — держит 40415
    13:36:26.621 ОТПУСКАЮ pid 40415

Держал дерево не «какой-то процесс 27713», а прогон набора СОСЕДНЕЙ планки,
стоявший в ту минуту на том же самом тесте. Один прогон на свободном дереве
зелёный; два — красные оба, и каждый по-своему: «собрано разное» у одного,
«герметично, но красное» у другого.

Цена этой ошибки не в ложном красном, а в подменённом смысле: ворота, которые
краснеют от шума, перестают читать — и настоящую зависимость от HOME, ради
которой они написаны, тоже.

Здесь заперто три утверждения:

  · чужой ЖИВОЙ держатель дерева — это «не смог измерить», а не вердикт о HOME;
  · ворота держат дерево, пока меряют, — чтобы второй харнесс отказался вслух;
  · обратный контроль: без чужого замка расхождение чисел по-прежнему красное.

Тест самодостаточен: только стандартная библиотека и сам инструмент.
"""
from __future__ import annotations

import importlib.util
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]

_спек = importlib.util.spec_from_file_location(
    "ss_gauntl" "et_hermet" "ic_race", РЕПО / "tools" / "gauntlet.py")
gt = importlib.util.module_from_spec(_спек)
_спек.loader.exec_module(gt)

#: Пид, который есть всегда и точно не наш. Тот же приём, что в
#: tests/test_mutation_lock.py: «жив и чужой» без запуска чужого процесса.
ЧУЖОЙ_ЖИВОЙ = 1


class Дерево(unittest.TestCase):
    """Своё дерево и свой замок: рабочее дерево человека тут ни при чём."""

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.корень = Path(tmp.name)
        self.addCleanup(setattr, gt, "PLUG", gt.PLUG)
        gt.PLUG = self.корень
        self.прогоны = []

    def _наборы(self, *исходы):
        """Подменить прогон набора заранее известными числами.

        Настоящий набор тут не нужен и вреден: проверяется СБОРКА вердикта,
        а прогон занял бы минуты и притащил бы в тест всё содержимое дерева.
        """
        очередь = list(исходы)
        замок = self.корень / ".mutation-lock"

        def прогон(env=None):
            self.прогоны.append({
                "env": env,
                "замок": замок.read_text("utf-8") if замок.is_file() else None})
            return очередь.pop(0)

        self.addCleanup(setattr, gt, "_suite", gt._suite)
        gt._suite = прогон

    def занять_чужим(self, pid: int = ЧУЖОЙ_ЖИВОЙ,
                     кто: str = "набор: tests/test_чужой.py::Класс::тест") -> None:
        (self.корень / ".mutation-lock").write_text(f"{pid} {кто}\n",
                                                    encoding="utf-8")


class ГонкаЗаЗамокНеЕстьЗависимостьОтHOME(Дерево):

    def test_чужой_живой_замок_не_даёт_вердикта_про_HOME(self):
        """Главное утверждение файла: расхождение рядом с чужим прогоном
        нельзя объявлять зависимостью набора от домашнего каталога."""
        self._наборы((0, 2435, 0, "", []), (1, 2434, 1, "", []))
        self.занять_чужим()

        v = gt.gate_hermetic()

        self.assertEqual(v["status"], "unknown", v)
        self.assertNotIn("при разном HOME", v["detail"], v)
        self.assertNotIn("герметично, но красное", v["detail"], v)

    def test_отказ_называет_чей_прогон_держит_дерево(self):
        """Номер без имени — не улика: процесс 27713 установить не удалось."""
        self._наборы((0, 2435, 0, "", []), (1, 2434, 1, "", []))
        self.занять_чужим(кто="набор: tests/test_чужой.py::Класс::тест")

        v = gt.gate_hermetic()

        self.assertEqual(v["lock"]["pid"], ЧУЖОЙ_ЖИВОЙ, v)
        self.assertIn("tests/test_чужой.py", v["lock"]["кто"], v)
        self.assertIn("tests/test_чужой.py", v["detail"], v)

    def test_рядом_с_чужим_прогоном_набор_даже_не_гоняется(self):
        """Мерить дерево, которое держит кто-то ещё, нечем: два харнесса
        меряют друг друга, а не код. Четыре минуты прогона ради заведомо
        нечитаемого числа — плата ни за что."""
        self._наборы((0, 2435, 0, "", []), (1, 2434, 1, "", []))
        self.занять_чужим()

        gt.gate_hermetic()

        self.assertEqual(self.прогоны, [], "набор гонялся на занятом дереве")

    def test_мёртвый_держатель_не_мешает_мерить(self):
        """Обратный контроль замка: вечная блокировка от убитого прогона —
        это отказ мерить навсегда, то есть та же поломка с другой стороны."""
        self.занять_чужим(pid=_мёртвый_пид(), кто="планка: --gate мутации")
        self._наборы((0, 2435, 0, "", []), (0, 2435, 0, "", []))

        v = gt.gate_hermetic()

        self.assertEqual(v["status"], "pass", v)


class БезЧужогоЗамкаВоротаОстаютсяСтрогими(Дерево):
    """Обратный контроль: ворота, переставшие краснеть, бесполезны так же,
    как ворота, краснеющие от шума."""

    def test_расхождение_чисел_по_прежнему_красное(self):
        self._наборы((0, 2435, 0, "", []), (1, 2434, 1, "", []))

        v = gt.gate_hermetic()

        self.assertEqual(v["status"], "fail", v)
        self.assertIn("при разном HOME собрано разное", v["detail"], v)

    def test_одинаково_красный_набор_остаётся_красным(self):
        self._наборы((1, 2434, 1, "", []), (1, 2434, 1, "", []))

        v = gt.gate_hermetic()

        self.assertEqual(v["status"], "fail", v)
        self.assertIn("герметично, но красное", v["detail"], v)

    def test_зелёное_остаётся_зелёным(self):
        self._наборы((0, 2435, 0, "", []), (0, 2435, 0, "", []))

        v = gt.gate_hermetic()

        self.assertEqual(v["status"], "pass", v)


class ВоротаДержатДеревоПокаМеряют(Дерево):
    """Отказ второму харнессу возможен только если первый ОБЪЯВИЛ себя.

    Пока ворота меряли молча, два прогона планки спокойно уходили в один
    набор — и портили измерения друг другу, каждый относя чужую поломку на
    свой счёт. Ровно та болезнь, ради которой замок и заведён этажом ниже.
    """

    def test_на_время_обоих_прогонов_замок_наш(self):
        self._наборы((0, 2435, 0, "", []), (0, 2435, 0, "", []))

        gt.gate_hermetic()

        self.assertEqual(len(self.прогоны), 2, self.прогоны)
        for п in self.прогоны:
            self.assertIsNotNone(п["замок"], "дерево не объявлено занятым")
            self.assertEqual(п["замок"].split()[0], str(os.getpid()), п)

    def test_после_измерения_дерево_отпущено(self):
        self._наборы((0, 2435, 0, "", []), (0, 2435, 0, "", []))

        gt.gate_hermetic()

        self.assertFalse((self.корень / ".mutation-lock").exists(),
                         "замок пережил измерение — следующий прогон будет "
                         "ждать процесса, которого уже нет")


def _мёртвый_пид() -> int:
    """Пид процесса, который точно завершился и уже пожат."""
    p = subprocess.Popen([sys.executable, "-c", "pass"])
    p.wait()
    return p.pid


if __name__ == "__main__":
    unittest.main()
